  e.rot = e.div.firstChild;
  return e;
}
const A = '\u20D7';                       // combining right arrow above
const HAT_I = 'i\u0302', HAT_J = 'j\u0302', HAT_K = 'k\u0302';

const lbX = addLabel('<i>x</i>', new THREE.Vector3(), { bold: true, fontSize: '15px', offset: [0, 14] });
const lbY = addLabel('<i>y</i>', new THREE.Vector3(), { bold: true, fontSize: '15px', offset: [16, 8] });
const lbZ = addLabel('<i>z</i>', new THREE.Vector3(), { bold: true, fontSize: '15px', offset: [0, -14] });

