registerInteractive(arX, { title: 'Component A\u20D7x', tooltip: 'x-component', body: 'A\u20D7x = Ax î lies along the x-axis and forms one edge of the dashed box. Its length is |Ax|.' });
registerInteractive(arY, { title: 'Component A\u20D7y', tooltip: 'y-component', body: 'A\u20D7y = Ay ĵ lies along the y-axis, perpendicular to both other components.' });
registerInteractive(arZ, { title: 'Component A\u20D7z', tooltip: 'z-component', body: 'A\u20D7z = Az k̂ rises along the z-axis; it lifts the tip of A\u20D7 off the xy-plane.' });
registerInteractive(arR, { title: 'Resultant A\u20D7', tooltip: 'the resultant', body: 'A\u20D7 = A\u20D7x + A\u20D7y + A\u20D7z is the body diagonal of the box, with magnitude |A\u20D7| = √(Ax² + Ay² + Az²).' });

/* ── state ─────────────────────────────────────────────────────────────── */
const cur = { ax: 3, ay: 4, az: 4, chain: 0 };
