     figure z  → world +Y   (screen up)
   origin dot  → SphereGeometry(0.07)                              black
   axis x,y,z  → Cylinder shaft r=0.02 + Cone(r=0.09,h=0.3)        black
   dashed box  → LineSegments (12 edges) + LineDashedMaterial      dark grey
   A_x,A_y,A_z → Cylinder r=0.10 + Cone(r=0.26,h=0.55)             navy #1B4F72
   ghost A_y,A_z → same arrows, opacity 0.25, origin-anchored      navy
   A resultant → Cylinder r=0.095 + Cone(r=0.25,h=0.55)            red  #C0392B
   right-triangle guides → thin solid LineSegments                 grey
   labels      → addLabel HTML (vector over-arrows + hats), rotated to the
                 on-screen direction of each arrow
───────────────────────────────────────────────────────────────────────────*/

const EX = new THREE.Vector3(0, 0, 1);   // figure x  (toward viewer, lower-left)
const EY = new THREE.Vector3(1, 0, 0);   // figure y  (screen right)
const EZ = new THREE.Vector3(0, 1, 0);   // figure z  (up)
const ORIGIN = new THREE.Vector3(0, 0, 0);

const NAVY = 0x1B4F72, RED = 0xC0392B, BLACK = 0x111111;

/* ── arrow factory ─────────────────────────────────────────────────────── */
function makeArrow(color, o = {}) {
  const shaftR = o.shaftR ?? 0.1, headR = o.headR ?? 0.26, headL = o.headL ?? 0.55;
  const g = new THREE.Group();
  const mat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: o.opacity ?? 1 });
  const sg = new THREE.CylinderGeometry(shaftR, shaftR, 1, 16); sg.translate(0, 0.5, 0);
  const shaft = new THREE.Mesh(sg, mat);
  const hg = new THREE.ConeGeometry(headR, headL, 24); hg.translate(0, -headL / 2, 0);
  const head = new THREE.Mesh(hg, mat);
  g.add(shaft); g.add(head);
  g.userData.mat = mat;
  const up = new THREE.Vector3(0, 1, 0), dv = new THREE.Vector3();
  g.userData.set = (start, end) => {
    dv.subVectors(end, start);
    const len = dv.length();
    if (len < 0.03) { g.visible = false; return; }
    g.visible = true;
    g.position.copy(start);
    g.quaternion.setFromUnitVectors(up, dv.clone().normalize());
    const hl = Math.min(headL, len * 0.55);
    head.scale.setScalar(hl / headL);
    head.position.set(0, len, 0);
    shaft.scale.y = Math.max(len - hl * 0.85, 1e-3);
  };
  scene.add(g);
  return g;
}

/* ── origin dot ────────────────────────────────────────────────────────── */
const originDot = new THREE.Mesh(
  new THREE.SphereGeometry(0.07, 16, 12),
  new THREE.MeshBasicMaterial({ color: BLACK })
);
scene.add(originDot);

/* ── axes ──────────────────────────────────────────────────────────────── */
const axisOpt = { shaftR: 0.02, headR: 0.09, headL: 0.3 };
const axX = makeArrow(BLACK, axisOpt);
const axY = makeArrow(BLACK, axisOpt);
const axZ = makeArrow(BLACK, axisOpt);

/* ── dashed box ────────────────────────────────────────────────────────── */
const boxGeo = new THREE.BufferGeometry();
const boxPos = new Float32Array(24 * 3);
boxGeo.setAttribute('position', new THREE.BufferAttribute(boxPos, 3));
const boxMat = new THREE.LineDashedMaterial({ color: 0x333333, dashSize: 0.15, gapSize: 0.1 });
const boxLines = new THREE.LineSegments(boxGeo, boxMat);
scene.add(boxLines);

const EDGES = [];
for (let j = 0; j < 2; j++) for (let k = 0; k < 2; k++) EDGES.push([[0, j, k], [1, j, k]]);
for (let i = 0; i < 2; i++) for (let k = 0; k < 2; k++) EDGES.push([[i, 0, k], [i, 1, k]]);
for (let i = 0; i < 2; i++) for (let j = 0; j < 2; j++) EDGES.push([[i, j, 0], [i, j, 1]]);

/* ── right-triangle guides ─────────────────────────────────────────────── */
const triGeo = new THREE.BufferGeometry();
const triPos = new Float32Array(4 * 3);
triGeo.setAttribute('position', new THREE.BufferAttribute(triPos, 3));
const triLines = new THREE.LineSegments(triGeo, new THREE.LineBasicMaterial({ color: 0x888888 }));
triLines.visible = false;
scene.add(triLines);

/* ── component + resultant arrows ──────────────────────────────────────── */
const arX = makeArrow(NAVY);
const arY = makeArrow(NAVY);
const arZ = makeArrow(NAVY);
const ghY = makeArrow(NAVY, { opacity: 0.25 });
const ghZ = makeArrow(NAVY, { opacity: 0.25 });
const arR = makeArrow(RED, { shaftR: 0.095, headR: 0.25, headL: 0.55 });
ghY.visible = false; ghZ.visible = false;

registerInteractive(arX, { title: 'Component A\u20D7x', tooltip: 'x-component', body: 'A\u20D7x = Ax \u00EE lies along the x-axis and forms one edge of the dashed box. Its length is |Ax|.' });
registerInteractive(arY, { title: 'Component A\u20D7y', tooltip: 'y-component', body: 'A\u20D7y = Ay \u0135 lies along the y-axis, perpendicular to both other components.' });
registerInteractive(arZ, { title: 'Component A\u20D7z', tooltip: 'z-component', body: 'A\u20D7z = Az k\u0302 rises along the z-axis; it lifts the tip of A\u20D7 off the xy-plane.' });
registerInteractive(arR, { title: 'Resultant A\u20D7', tooltip: 'the resultant', body: 'A\u20D7 = A\u20D7x + A\u20D7y + A\u20D7z is the body diagonal of the dashed box, with magnitude |A\u20D7| = \u221A(Ax\u00B2 + Ay\u00B2 + Az\u00B2).' });

/* ── state ─────────────────────────────────────────────────────────────── */
const cur = { ax: 3, ay: 4, az: 4, chain: 0 };
const tgt = { ax: 3, ay: 4, az: 4, chain: 0 };
let build = null;

function corner(i, j, k) {
  return new THREE.Vector3()
    .addScaledVector(EX, cur.ax * i)
    .addScaledVector(EY, cur.ay * j)
    .addScaledVector(EZ, cur.az * k);
}

/* ── labels (declared BEFORE any updateScene call) ─────────────────────── */
function rotLabel(html, opts) {
  const e = addLabel('<span style="display:inline-block">' + html + '</span>', new THREE.Vector3(), opts);
  e.rot = e.div.firstChild;
  return e;
}
const VA = '\u20D7';                       // combining right arrow above
const HAT_I = '\u00EE', HAT_J = '\u0135', HAT_K = 'k\u0302';

const lbX = addLabel('<i>x</i>', new THREE.Vector3(), { bold: true, fontSize: '16px', offset: [-6, 16] });
const lbY = addLabel('<i>y</i>', new THREE.Vector3(), { bold: true, fontSize: '16px', offset: [14, 10] });
const lbZ = addLabel('<i>z</i>', new THREE.Vector3(), { bold: true, fontSize: '16px', offset: [-4, -14] });

const lbAx = rotLabel('<b>A' + VA + '</b><sub>x</sub> = <i>A<sub>x</sub></i><b>' + HAT_I + '</b>',
  { color: '#1B4F72', fontSize: '13px', bold: false, offset: [30, 16] });
const lbAy = rotLabel('<b>A' + VA + '</b><sub>y</sub> = <i>A<sub>y</sub></i><b>' + HAT_J + '</b>',
  { color: '#1B4F72', fontSize: '13px', offset: [0, -16] });
const lbAz = rotLabel('<b>A' + VA + '</b><sub>z</sub> = <i>A<sub>z</sub></i><b>' + HAT_K + '</b>',
  { color: '#1B4F72', fontSize: '13px', offset: [-26, 0] });
const lbR = rotLabel('<b>A' + VA + '</b> = <b>A' + VA + '</b><sub>x</sub> + <b>A' + VA + '</b><sub>y</sub> + <b>A' + VA + '</b><sub>z</sub>',
  { color: '#C0392B', fontSize: '13px', offset: [-18, -14] });
const lbMag = addLabel('', new THREE.Vector3(), { fontSize: '12px', color: '#C0392B', offset: [34, -16] });

function screenAngle(p1, p2) {
  const a = p1.clone().project(camera), b = p2.clone().project(camera);
  const dx = (b.x - a.x) * canvas.clientWidth;
  const dy = -(b.y - a.y) * canvas.clientHeight;
  if (Math.abs(dx) < 1e-6 && Math.abs(dy) < 1e-6) return 0;
  let ang = Math.atan2(dy, dx) * 180 / Math.PI;
  if (ang > 90) ang -= 180;
  if (ang < -90) ang += 180;
  return ang;
}

/* ── scene update ──────────────────────────────────────────────────────── */
function updateScene() {
  const Px = EX.clone().multiplyScalar(cur.ax);
  const Py = EY.clone().multiplyScalar(cur.ay);
  const Pz = EZ.clone().multiplyScalar(cur.az);
  const tip = Px.clone().add(Py).add(Pz);

  // axes (extend a little past the box corners)
  const lx = Math.max(cur.ax + 0.8, 2.2), ly = Math.max(cur.ay + 0.8, 2.2), lz = Math.max(cur.az + 0.8, 2.2);
  axX.userData.set(ORIGIN, EX.clone().multiplyScalar(lx));
  axY.userData.set(ORIGIN, EY.clone().multiplyScalar(ly));
  axZ.userData.set(ORIGIN, EZ.clone().multiplyScalar(lz));

  // dashed box
  let o = 0;
  for (const [a, b] of EDGES) {
    const p = corner(a[0], a[1], a[2]), q = corner(b[0], b[1], b[2]);
    boxPos[o++] = p.x; boxPos[o++] = p.y; boxPos[o++] = p.z;
    boxPos[o++] = q.x; boxPos[o++] = q.y; boxPos[o++] = q.z;
  }
  boxGeo.attributes.position.needsUpdate = true;
  boxGeo.computeBoundingSphere();
  boxLines.computeLineDistances();

  // right-triangle guides: O → (x+y corner) → tip
  const xy = Px.clone().add(Py);
  triPos.set([0, 0, 0, xy.x, xy.y, xy.z, xy.x, xy.y, xy.z, tip.x, tip.y, tip.z]);
  triGeo.attributes.position.needsUpdate = true;
  triGeo.computeBoundingSphere();

  // component arrows (build = staged head-to-tail animation)
  const fX = build === null ? 1 : THREE.MathUtils.clamp(build - 0, 0, 1);
  const fY = build === null ? 1 : THREE.MathUtils.clamp(build - 1, 0, 1);
  const fZ = build === null ? 1 : THREE.MathUtils.clamp(build - 2, 0, 1);

  const bX = ORIGIN.clone();
  const bY = Px.clone().multiplyScalar(cur.chain);
  const bZ = Px.clone().add(Py).multiplyScalar(cur.chain);

  arX.userData.set(bX, bX.clone().addScaledVector(EX, cur.ax * fX));
  arY.userData.set(bY, bY.clone().addScaledVector(EY, cur.ay * fY));
  arZ.userData.set(bZ, bZ.clone().addScaledVector(EZ, cur.az * fZ));
  arR.userData.set(ORIGIN, tip);

  const showGhost = cur.chain > 0.03;
  ghY.visible = showGhost; ghZ.visible = showGhost;
  if (showGhost) {
    const gOp = 0.25 * cur.chain;
    ghY.userData.mat.opacity = gOp; ghZ.userData.mat.opacity = gOp;
    ghY.userData.set(ORIGIN, Py);
    ghZ.userData.set(ORIGIN, Pz);
  }

  // label anchors
  lbX.pos.copy(EX).multiplyScalar(lx + 0.3);
  lbY.pos.copy(EY).multiplyScalar(ly + 0.3);
  lbZ.pos.copy(EZ).multiplyScalar(lz + 0.3);

  lbAx.pos.copy(bX).addScaledVector(EX, cur.ax * 0.55 * fX);
  lbAy.pos.copy(bY).addScaledVector(EY, cur.ay * 0.55 * fY);
  lbAz.pos.copy(bZ).addScaledVector(EZ, cur.az * 0.5 * fZ);
  lbR.pos.copy(tip).multiplyScalar(0.48);
  lbMag.pos.copy(tip);

  lbAx.rot.style.transform = 'rotate(' + screenAngle(bX, bX.clone().addScaledVector(EX, 1)).toFixed(1) + 'deg)';
  lbAy.rot.style.transform = 'rotate(' + screenAngle(bY, bY.clone().addScaledVector(EY, 1)).toFixed(1) + 'deg)';
  lbAz.rot.style.transform = 'rotate(' + screenAngle(bZ, bZ.clone().addScaledVector(EZ, 1)).toFixed(1) + 'deg)';
  if (tip.length() > 0.3) {
    lbR.rot.style.transform = 'rotate(' + screenAngle(ORIGIN, tip).toFixed(1) + 'deg)';
  }

  lbAx.div.style.opacity = cur.ax * fX > 0.3 ? 1 : 0;
  lbAy.div.style.opacity = cur.ay * fY > 0.3 ? 1 : 0;
  lbAz.div.style.opacity = cur.az * fZ > 0.3 ? 1 : 0;
  lbR.div.style.opacity = tip.length() > 0.5 ? 1 : 0;

  const mag = Math.sqrt(cur.ax * cur.ax + cur.ay * cur.ay + cur.az * cur.az);
  const magTxt = '|<b>A' + VA + '</b>| = ' + mag.toFixed(2);
  if (lbMag._t !== magTxt) { lbMag.div.innerHTML = magTxt; lbMag._t = magTxt; }
  lbMag.div.style.opacity = mag > 0.5 ? 1 : 0;
}

/* ── first build, then camera (geometry must exist for the auto-fit) ───── */
updateScene();
setCameraView({
  projection: 'orthographic',
  axisScreenAngles: { x: 7, z: 43 },   // measured off the source: y ~horizontal, x ~43° down-left
  heightFraction: 0.72
});
updateScene();                          // refresh label rotations for the final camera

document.getElementById('btnReset').style.display = '';
document.getElementById('btnReset').textContent = 'Reset view';

/* ── UI wiring ─────────────────────────────────────────────────────────── */
const sAx = document.getElementById('axSlider');
const sAy = document.getElementById('aySlider');
const sAz = document.getElementById('azSlider');
const vAx = document.getElementById('axVal');
const vAy = document.getElementById('ayVal');
const vAz = document.getElementById('azVal');
const magOut = document.getElementById('magOut');

function setActive(ids, id) {
  ids.forEach(i => document.getElementById(i).classList.toggle('active', i === id));
}
const CASE_IDS = ['caseX', 'caseXY', 'caseXYZ'];
const MODE_IDS = ['modeEdges', 'modeHT'];

function syncPresets() {
  let id = 'caseXYZ';
  if (tgt.ay < 0.05 && tgt.az < 0.05) id = 'caseX';
  else if (tgt.az < 0.05) id = 'caseXY';
  setActive(CASE_IDS, id);
}
function setComponents(ax, ay, az) {
  tgt.ax = ax; tgt.ay = ay; tgt.az = az;
  sAx.value = ax; sAy.value = ay; sAz.value = az;
  syncPresets();
}
function setMode(ht) {
  tgt.chain = ht ? 1 : 0;
  setActive(MODE_IDS, ht ? 'modeHT' : 'modeEdges');
}

sAx.addEventListener('input', () => { tgt.ax = +sAx.value; syncPresets(); });
sAy.addEventListener('input', () => { tgt.ay = +sAy.value; syncPresets(); });
sAz.addEventListener('input', () => { tgt.az = +sAz.value; syncPresets(); });

document.getElementById('caseX').onclick = () => { build = null; setComponents(3, 0, 0); };
document.getElementById('caseXY').onclick = () => { build = null; setComponents(3, 4, 0); };
document.getElementById('caseXYZ').onclick = () => { build = null; setComponents(3, 4, 4); };

document.getElementById('modeEdges').onclick = () => { build = null; setMode(false); };
document.getElementById('modeHT').onclick = () => { build = null; setMode(true); };

document.getElementById('btnPlay').onclick = () => {
  setMode(true);
  cur.chain = 1;
  build = 0;
};

document.getElementById('chkTri').addEventListener('change', e => {
  triLines.visible = e.target.checked;
});

/* ── guided demo ───────────────────────────────────────────────────────── */
const steps = [
  {
    title: 'One component only', ax: 3, ay: 0, az: 0, ht: false,
    narr: 'With only A\u2093 nonzero the box collapses to a single segment: the red resultant lies right on top of the blue x-arrow. An axis-aligned vector needs just one number.'
  },
  {
    title: 'Two components \u2014 a planar vector', ax: 3, ay: 4, az: 0, ht: false,
    narr: 'Adding A\u1D67 opens the box into a flat rectangle in the xy-plane; the red arrow is now the diagonal of that rectangle, with magnitude \u221A(A\u2093\u00B2 + A\u1D67\u00B2).'
  },
  {
    title: 'Three components \u2014 a space vector', ax: 3, ay: 4, az: 4, ht: false,
    narr: 'Raising A\u2098 (the z-component) inflates the rectangle into the dashed box and the red arrow becomes its body diagonal, reaching the far corner: |A| = \u221A(A\u2093\u00B2 + A\u1D67\u00B2 + A_z\u00B2).'
  },
  {
    title: 'Head-to-tail equivalence', ax: 3, ay: 4, az: 4, ht: true,
    narr: 'The same three blue arrows relaid tip to tail along box edges still land exactly on the red arrowhead \u2014 decomposition and vector addition are one statement.'
  }
];
let stepIdx = 2;
function goToStep(i) {
  stepIdx = (i + steps.length) % steps.length;
  const s = steps[stepIdx];
  build = null;
  setComponents(s.ax, s.ay, s.az);
  setMode(s.ht);
  document.getElementById('stepTitle').textContent = (stepIdx + 1) + '. ' + s.title;
  document.getElementById('stepNarr').textContent = s.narr;
}
document.getElementById('stepPrev').onclick = () => goToStep(stepIdx - 1);
document.getElementById('stepNext').onclick = () => goToStep(stepIdx + 1);
goToStep(2);
cur.ax = 3; cur.ay = 4; cur.az = 4;   // start already at the printed figure

/* ── tween ticker ──────────────────────────────────────────────────────── */
let _lastTick = performance.now();
function tick() {
  requestAnimationFrame(tick);
  const now = performance.now();
  const dt = Math.min(0.05, (now - _lastTick) / 1000);
  _lastTick = now;
  const k = Math.min(1, dt * 6);
  cur.ax += (tgt.ax - cur.ax) * k;
  cur.ay += (tgt.ay - cur.ay) * k;
  cur.az += (tgt.az - cur.az) * k;
  cur.chain += (tgt.chain - cur.chain) * k;
  if (build !== null) { build += dt / 1.2; if (build > 3.4) build = null; }

  vAx.textContent = cur.ax.toFixed(1);
  vAy.textContent = cur.ay.toFixed(1);
  vAz.textContent = cur.az.toFixed(1);
  const m = Math.sqrt(cur.ax * cur.ax + cur.ay * cur.ay + cur.az * cur.az);
  magOut.innerHTML = '|A| = &radic;(A<sub>x</sub>&sup2;+A<sub>y</sub>&sup2;+A<sub>z</sub>&sup2;) = ' + m.toFixed(2);

  updateScene();
}
tick();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

